package edu.ankara.audiometer.domain.validation;
import edu.ankara.audiometer.domain.config.*;import edu.ankara.audiometer.domain.model.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class AudiometryValidatorsTest { @Test void validatesFrequencyAndIntensity(){ var c=AudiometryConfig.defaults(); assertTrue(AudiometryValidators.validateFrequency(new FrequencyHz(1000),c).valid()); assertFalse(AudiometryValidators.validateFrequency(new FrequencyHz(125),c).valid()); assertTrue(AudiometryValidators.validateIntensity(new IntensityDbHL(40),c).valid()); assertFalse(AudiometryValidators.validateIntensity(new IntensityDbHL(140),c).valid()); } @Test void sessionCompletenessFailsWhenMissing(){ assertFalse(AudiometryValidators.validateSessionCompleteness(TestState.initial(AudiometryConfig.defaults())).valid()); } }
